from qiskit import QuantumCircuit

def build_constraint_1(qc, problem_qubits, flag, scratch):
    """
    Clause 1: (x0 OR NOT x1 OR x2)
    Flips flag iff clause satisfied.
    """
    # False when: x0=0, x1=1, x2=0
    # Invert pattern: invert x0, keep x1, invert x2
    invert = [True, False, True]   # True means apply X before control
    temp = scratch[0]
    anc = scratch[1]  # extra ancilla for mcx decomp

    # Compute temp = (x0=0 AND x1=1 AND x2=0)
    for i, do_invert in enumerate(invert):
        if do_invert:
            qc.x(problem_qubits[i])
    qc.mcx(problem_qubits, temp, ancilla_qubits=[anc])
    for i, do_invert in enumerate(invert):
        if do_invert:
            qc.x(problem_qubits[i])

    # Flip flag if temp==0 (clause true)
    qc.x(temp)
    qc.cx(temp, flag)
    qc.x(temp)

    # Uncompute temp
    for i, do_invert in enumerate(invert):
        if do_invert:
            qc.x(problem_qubits[i])
    qc.mcx(problem_qubits, temp, ancilla_qubits=[anc])
    for i, do_invert in enumerate(invert):
        if do_invert:
            qc.x(problem_qubits[i])


