    """
    Clause 2: (NOT x0 OR NOT x1 OR x2)
    """
    # False when: x0=1, x1=1, x2=0
    invert = [False, False, True]   # invert x2, keep others
    temp = scratch[0]
    anc = scratch[1]

    for i, do_invert in enumerate(invert):
        if do_invert:
            qc.x(problem_qubits[i])
    qc.mcx(problem_qubits, temp, ancilla_qubits=[anc])
    for i, do_invert in enumerate(invert):
        if do_invert:
            qc.x(problem_qubits[i])

    qc.x(temp)
    qc.cx(temp, flag)
    qc.x(temp)

    for i, do_invert in enumerate(invert):
        if do_invert:
            qc.x(problem_qubits[i])
    qc.mcx(problem_qubits, temp, ancilla_qubits=[anc])
    for i, do_invert in enumerate(invert):
        if do_invert:
            qc.x(problem_qubits[i])


def build_constraint_3(qc, problem_qubits, flag, scratch):
    """
    Clause 3: (NOT x0 OR NOT x1 OR NOT x2)
