from qiskit import QuantumCircuit

def build_constraint_1(qc, problem_qubits, flag, scratch):
    # edge (0,1)
    a0, a1 = problem_qubits[0], problem_qubits[1]
    b0, b1 = problem_qubits[2], problem_qubits[3]
    # scratch[1] will hold the equality flag, scratch[0] unused
    terms = [
        (0,0,0,0),  # both color 0
        (0,0,1,1),  # A=0, B=3
        (1,0,1,0),  # both color 1
        (0,1,0,1),  # both color 2
        (1,1,0,0),  # A=3, B=0
        (1,1,1,1),  # both color 3
    ]
    controls = [a0, a1, b0, b1]

    # Compute equality into scratch[1]
    for term in terms:
        for q, val in zip(controls, term):
            if val == 0:
                qc.x(q)
        qc.mcx(controls, scratch[1], mode='noancilla')
        for q, val in zip(controls, term):
            if val == 0:
                qc.x(q)

    # Flip flag if colors differ (inequality)
    qc.x(scratch[1])
    qc.cx(scratch[1], flag)
    qc.x(scratch[1])

    # Uncompute equality (same operations again)
    for term in terms:
        for q, val in zip(controls, term):
            if val == 0:
                qc.x(q)
        qc.mcx(controls, scratch[1], mode='noancilla')
        for q, val in zip(controls, term):
            if val == 0:
                qc.x(q)


